param(
  [string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot),
  [string]$DefaultOutputPath=(Join-Path $ProjectRoot 'artifacts\s61\s61-default-first-screen-1938x1158.png'),
  [string]$WideOutputPath=(Join-Path $ProjectRoot 'artifacts\s61\s61-script-interface-1938x1158.png'),
  [string]$CompactOutputPath=(Join-Path $ProjectRoot 'artifacts\s61\s61-script-interface-1366x768.png')
)
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$condition,[string]$message){if(-not$condition){throw $message}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function Shot([string]$path,[int]$targetWidth,[int]$targetHeight){$dir=Split-Path -Parent $path;if(-not(Test-Path $dir)){[IO.Directory]::CreateDirectory($dir)|Out-Null};$window.UpdateLayout();$dpiX=96*$targetWidth/[Math]::Max(1,$window.ActualWidth);$dpiY=96*$targetHeight/[Math]::Max(1,$window.ActualHeight);$render=New-Object Windows.Media.Imaging.RenderTargetBitmap($targetWidth,$targetHeight,$dpiX,$dpiY,[Windows.Media.PixelFormats]::Pbgra32);$render.Render($window);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($render));$stream=[IO.File]::Open([IO.Path]::GetFullPath($path),[IO.FileMode]::Create);try{$encoder.Save($stream)}finally{$stream.Dispose()};"${targetWidth}x${targetHeight} (WPF render)"}
$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s61-ui-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$memberType=$assembly.GetType('HalconWinFormsDemo.Models.VmScriptInterfaceMemberData',$true);$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function F([string]$name){$field=$main.GetField($name,$all);if($null-eq$field){return $null};$value=$field.GetValue($window);Write-Output -NoEnumerate $value}
function M([string]$name,[object[]]$parameters=@()){$main.GetMethod($name,$private).Invoke($window,$parameters)}
function Member([string]$direction,[string]$type,[string]$name,[string]$defaultValue,[bool]$required,[string]$description){$m=[Activator]::CreateInstance($memberType);$m.MemberId=[Guid]::NewGuid().ToString('N');$m.Direction=$direction;$m.ValueType=$type;$m.Name=$name;$m.DefaultValue=$defaultValue;$m.IsRequired=$required;$m.Description=$description;$m.Normalize();$m}
$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown}
try{
  $window.Topmost=$true;$window.Show();$window.WindowState=[Windows.WindowState]::Normal;$window.MinWidth=0;$window.MinHeight=0;$window.Left=2;$window.Top=2;$window.Width=1938;$window.Height=1158;Pump 550
  Assert((F 'ScriptInterfaceWorkspace').Visibility.ToString()-eq'Collapsed') 'Script interface workspace is visible on default first screen';Assert((F 'DeveloperToolbarPanel').Children.Count-eq7) 'A permanent toolbar command was added';$default=Shot $DefaultOutputPath 1938 1158
  $script=M 'CreateFlowTool' ([object[]]@([Enum]::Parse($kindType,'CSharpDllScript'),'Inspection Script',$true,$null));$flow=F 'flowTools';$flow.Add($script)
  foreach($m in @((Member Input Number Width '' $true 'Measured width from the selected upstream port.'),(Member Input String PartNo '' $false 'Optional product identifier.'),(Member Input Boolean Enabled '' $true 'Station enable state.'),(Member Input ResultCode PreviousResult '' $true 'Previous inspection decision.'),(Member Parameter Number Tolerance '0.15' $false 'Maximum accepted deviation.'),(Member Parameter Boolean UseCompensation 'true' $false 'Enable compensation before output.'),(Member Output Number CorrectedWidth '' $true 'Corrected width for downstream judgement.'),(Member Output ResultCode Result '' $true 'Normalized OK or NG decision.'))){$script.Parameters.ScriptInterfaceMembers.Add($m)}
  (F 'FlowToolList').SelectedItem=$script;M 'OpenScriptInterfaceButton_Click' ([object[]]@($null,$null))|Out-Null;Pump 450;(F 'ScriptInterfaceMemberListBox').SelectedIndex=6;Pump 180
  Assert((F 'ScriptInterfaceWorkspace').Visibility.ToString()-eq'Visible'-and(F 'MainWorkspaceGrid').Visibility.ToString()-eq'Collapsed') 'On-demand script interface workspace is not active';Assert((F 'ScriptInterfaceMemberListBox').ActualWidth-gt260-and(F 'ScriptInterfaceNameTextBox').ActualWidth-gt350) 'Wide interface workbench did not lay out correctly';$wide=Shot $WideOutputPath 1938 1158
  $window.Width=1366;$window.Height=768;$window.Left=2;$window.Top=2;Pump 600;Assert((F 'ScriptInterfaceMemberListBox').ActualHeight-gt260-and(F 'ScriptInterfaceSnippetTextBox').ActualWidth-gt300) 'Compact interface workbench is clipped';$compact=Shot $CompactOutputPath 1366 768
  Write-Output "S61_UI_CAPTURE=PASS; Default=$DefaultOutputPath; Wide=$WideOutputPath; Compact=$CompactOutputPath; DefaultSize=$default; WideSize=$wide; CompactSize=$compact; PermanentToolbarChildren=7; WorkspaceDefaultVisible=0; BSB=NOT_IMPLEMENTED_BY_USER_DIRECTIVE"
}finally{$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
